package com.portfolio.dto;
public class Db2Request { private String requestType; private int responseCode; private String connectionToken; private int sqlCode; private String errorMessage; public String getRequestType(){return requestType;} public void setRequestType(String v){requestType=v;} public int getResponseCode(){return responseCode;} public void setResponseCode(int v){responseCode=v;} public String getConnectionToken(){return connectionToken;} public void setConnectionToken(String v){connectionToken=v;} public int getSqlCode(){return sqlCode;} public void setSqlCode(int v){sqlCode=v;} public String getErrorMessage(){return errorMessage;} public void setErrorMessage(String v){errorMessage=v;} }
